from PIL import Image
import numpy as np
T=np.array(Image.open('/app/target.png').convert('L').resize((888,888),Image.Resampling.LANCZOS))<80
im=np.array(Image.open('/app/runs/stroke9/last/canvas_cam.jpg').convert('L'))
for th in [60,80,100]:
 A=im[68:956,68:956]<th;best=(0,None)
 for dy in range(-19,20):
  for dx in range(-19,20):
   a=max(0,dy);b=max(0,dx);c=max(0,-dy);d=max(0,-dx);h=888-max(a,c);w=888-max(b,d);tt=T[c:c+h,d:d+w];aa=A[a:a+h,b:b+w];i=(tt&aa).sum()/max(1,(tt|aa).sum())
   if i>best[0]:best=(i,(dx,dy,int((tt&aa).sum()),int(aa.sum()),int(tt.sum())))
 print(th,best)
PY
